import * as Cloudflare from "@alchemy.run/cloudflare";

/**
 * The D1 database for the Worker API.
 *
 * `migrations` points at the SQL files generated by drizzle-kit. Alchemy
 * applies pending migrations to D1 during every deploy.
 */
export const Database = Cloudflare.D1.Database("Database", {
  migrations: "./drizzle",
});
